class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        diff = [0] * 101
        for b, d in logs:
            diff[b - 1950] += 1
            diff[d - 1950] -= 1

        max_pop = 0
        best_year = 1950
        curr_pop = 0

        for i in range(101):
            curr_pop += diff[i]
            if curr_pop > max_pop:
                max_pop = curr_pop
                best_year = 1950 + i

        return best_year

class Solution {
public:
    int maximumPopulation(vector<vector<int>>& logs) {
        vector<int> diff(101, 0);
        for (const auto& log : logs) {
            diff[log[0] - 1950]++;
            diff[log[1] - 1950]--;
        }
        int maxPop = 0, bestYear = 1950, currPop = 0;
        for (int i = 0; i < 101; ++i) {
            currPop += diff[i];
            if (currPop > maxPop) {
                maxPop = currPop;
                bestYear = 1950 + i;
            }
        }
        return bestYear;
    }
};

